/**
 * On the test CI, we want to have multiple test runners in parallel.
 *
 * However, pulling down the densitydb repo to run the tests against each time is expensive.
 *
 * So, our strategy will be to serve the local files generated by generate_site.py,
 * and then any files not generated, we'll proxy the request to a CI proxy that has a copy of densitydb.
 */

import compression from 'compression'
import express from 'express'
import proxy from 'express-http-proxy'
import { z } from 'zod'

import { port } from '../../port'

import { github } from './github-utils'
import { UpstreamUsage } from './util'

/**
 * jsdelivr occasionally stalls on a file and answers with a 504 a full minute later, which is
 * long enough on its own to blow a test's time limit. This is a socket inactivity timeout, so a
 * large file that is downloading slowly but steadily isn't affected.
 */
const attemptTimeoutMs = 10_000
const attempts = 3

const usage: UpstreamUsage = { requests: 0, bytes: 0, sumMs: 0, busyMs: 0 }
let inFlight = 0
let busySince = 0

export function upstreamUsage(): UpstreamUsage {
    return { ...usage }
}

export function upstreamUsageSince(before: UpstreamUsage): UpstreamUsage {
    return {
        requests: usage.requests - before.requests,
        bytes: usage.bytes - before.bytes,
        sumMs: usage.sumMs - before.sumMs,
        busyMs: usage.busyMs - before.busyMs,
    }
}

/** Reached only once a request has missed the locally built site and is headed for the CDN. */
const trackUpstream: express.RequestHandler = (_, res, next) => {
    const start = Date.now()
    usage.requests++
    if (inFlight++ === 0) {
        busySince = start
    }
    // HTTP/1.1 serializes responses on a connection, so the socket's delta is this response's wire bytes.
    const { socket } = res
    const socketBytesAtStart = socket?.bytesWritten ?? 0
    res.on('close', () => {
        const now = Date.now()
        usage.bytes += Math.max((socket?.bytesWritten ?? 0) - socketBytesAtStart, 0)
        usage.sumMs += now - start
        if (--inFlight === 0) {
            usage.busyMs += now - busySince
        }
    })
    next()
}

const upstream: proxy.ProxyOptions = {
    timeout: attemptTimeoutMs,
    userResHeaderDecorator(headers, userReq) {
        const fileExtension = (/\.(.+)$/.exec(userReq.path))?.[1]
        const mimeType = fileExtension ? { html: 'text/html', js: 'text/javascript' }[fileExtension] : undefined
        // eslint-disable-next-line @typescript-eslint/no-unused-vars, no-restricted-syntax -- We're removing the context-security-policy header via destructuring
        const { 'content-security-policy': _, ...filteredHeaders } = headers
        return {
            ...filteredHeaders,
            'content-type': mimeType ?? headers['content-type'],
        }
    },
}

function jsdelivrProxy(sha: string): express.RequestHandler {
    return proxy(`https://cdn.jsdelivr.net`, {
        ...upstream,
        proxyReqPathResolver(req) {
            // We must get by SHA, since if we used branch name jsdelvir would cache the result for 12 hours and we couldn't get new changes from the branch
            return `/gh/densitydb/densitydb.github.io@${sha}${req.path}`
        },
        // A 404 is jsdelivr telling us the file isn't there, which is an answer. Anything else means
        // it didn't answer, so hand off to the next attempt and eventually to raw.githubusercontent.
        skipToNextHandlerFilter: (proxyRes) => {
            const status = proxyRes.statusCode ?? 500
            return status !== 404 && (status < 200 || status > 299)
        },
        proxyErrorHandler: (error, res, next) => { next() },
    })
}

/**
 * densitydb.github.io is around ninety times jsdelivr's 50MB package limit, so jsdelivr serves it
 * only as long as it doesn't have to weigh the package. When it does, it answers 403 and caches
 * that answer for twelve hours, which retries can't get past. raw has no size limit, and since we
 * only reach it when jsdelivr has already failed it never carries the bulk of the traffic.
 */
function rawGithubProxy(sha: string): express.RequestHandler {
    return proxy(`https://raw.githubusercontent.com`, {
        ...upstream,
        proxyReqPathResolver: req => `/densitydb/densitydb.github.io/${sha}${req.path}`,
    })
}

export async function startProxy(): Promise<void> {
    const { octokit } = await github()

    /**
     * If the user is using a branch that also exists on densitydb, we should use it as well.
     *
     * Otherwise, use `main`
     */
    const targetBranch = z.string().parse(process.env.URBANSTATS_BRANCH_NAME)

    const { data: remoteBranches } = await octokit.rest.repos.listBranches({
        owner: 'densitydb',
        repo: 'densitydb.github.io',
    })

    const branch = remoteBranches.find(({ name }) => name === targetBranch)
        ?? remoteBranches.find(({ name }) => name === 'main')
        ?? (() => { throw new Error('No main branch') })()

    // This is useful for debugging in case the proxy isn't working
    console.warn(`Proxy is using branch ${branch.name} (${branch.commit.sha})`)

    const app = express()

    app.use(compression({ enforceEncoding: 'gzip' }))

    const handlers: express.RequestHandler[] = []
    for (let attempt = 1; attempt <= attempts; attempt++) {
        if (attempt > 1) {
            handlers.push((req, res, next) => {
                console.warn(`jsdelivr did not serve ${req.path}; starting attempt ${attempt}`)
                next()
            })
        }
        handlers.push(jsdelivrProxy(branch.commit.sha))
    }
    handlers.push((req, res, next) => {
        console.warn(`jsdelivr did not serve ${req.path}; falling back to raw.githubusercontent`)
        next()
    })
    handlers.push(rawGithubProxy(branch.commit.sha))

    app.use(express.static('test/density-db'), trackUpstream, ...handlers)

    app.listen(port())
}
